import { test, expect } from '@playwright/test';

test.describe('The Internet - Navigation between home and example pages', () => {
  const baseUrl = 'https://the-internet.herokuapp.com';

  test.beforeEach(async ({ page }) => {
    await page.goto(baseUrl);
  });

  test('should display welcome heading on home page', async ({ page }) => {
    const heading = page.getByRole('heading', { name: /Welcome to the-internet/i });
    await expect(heading).toBeVisible();
  });

  test('should navigate to A/B Testing page and display h3 heading', async ({ page }) => {
    const abTestLink = page.getByRole('link', { name: /A\/B Testing/i });
    await expect(abTestLink).toBeVisible();

    await abTestLink.click();

    await expect(page).toHaveURL(/\/abtest/);

    const h3Heading = page.locator('h3');
    await expect(h3Heading).toBeVisible();
  });

  test('should navigate back to home page and show Available Examples heading', async ({ page }) => {
    const abTestLink = page.getByRole('link', { name: /A\/B Testing/i });
    await abTestLink.click();

    await expect(page).toHaveURL(/\/abtest/);

    await page.goBack();

    await expect(page).toHaveURL(baseUrl + '/');

    const availableExamplesHeading = page.getByRole('heading', { name: /Available Examples/i });
    await expect(availableExamplesHeading).toBeVisible();
  });

  test('should maintain navigation history when clicking back button', async ({ page }) => {
    const abTestLink = page.getByRole('link', { name: /A\/B Testing/i });

    await abTestLink.click();
    await expect(page).toHaveURL(/\/abtest/);

    const backButton = page.getByRole('link', { name: /Elementary/i }).first();
    await page.goBack();

    const welcomeHeading = page.getByRole('heading', { name: /Welcome to the-internet/i });
    await expect(welcomeHeading).toBeVisible();
  });
});
